import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int to, capacity, cost, rev;
        Edge(int to, int capacity, int cost, int rev) {
            this.to = to;
            this.capacity = capacity;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static class FlowNetwork {
        static final int MAXN = 5010;
        ArrayList<Edge>[] adj;
        int V;
        int[] h, dist, prevv, preve;

        @SuppressWarnings("unchecked")
        void setup(int n) {
            V = n;
            adj = new ArrayList[V];
            for (int i = 0; i < V; i++) {
                adj[i] = new ArrayList<>();
            }
            h = new int[V];
            dist = new int[V];
            prevv = new int[V];
            preve = new int[V];
        }

        void addEdge(int from, int to, int cap, int cost) {
            adj[from].add(new Edge(to, cap, cost, adj[to].size()));
            adj[to].add(new Edge(from, 0, -cost, adj[from].size() - 1));
        }

        int minCostFlow(int s, int t, int flow) {
            int totalCost = 0;
            Arrays.fill(h, 0);
            while (flow > 0) {
                PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
                Arrays.fill(dist, Integer.MAX_VALUE);
                dist[s] = 0;
                pq.offer(new int[]{0, s});
                while (!pq.isEmpty()) {
                    int[] cur = pq.poll();
                    int d = cur[0], v = cur[1];
                    if (dist[v] < d) continue;
                    for (int i = 0; i < adj[v].size(); i++) {
                        Edge e = adj[v].get(i);
                        if (e.capacity > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
                            dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            pq.offer(new int[]{dist[e.to], e.to});
                        }
                    }
                }
                if (dist[t] == Integer.MAX_VALUE) return -1;
                for (int v = 0; v < V; v++) h[v] += dist[v];
                int d = flow;
                for (int v = t; v != s; v = prevv[v]) {
                    d = Math.min(d, adj[prevv[v]].get(preve[v]).capacity);
                }
                flow -= d;
                totalCost += d * h[t];
                for (int v = t; v != s; v = prevv[v]) {
                    Edge e = adj[prevv[v]].get(preve[v]);
                    e.capacity -= d;
                    adj[v].get(e.rev).capacity += d;
                }
            }
            return totalCost;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int[] a = new int[50];
        int[] cnt = new int[50];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            a[i] = Integer.parseInt(st.nextToken());
            cnt[a[i] - 1]++;
        }

        List<Integer>[] e = new ArrayList[50];
        for (int i = 0; i < 50; i++) {
            e[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken()) - 1;
            int y = Integer.parseInt(st.nextToken()) - 1;
            e[x].add(y);
            e[y].add(x);
        }

        FlowNetwork flow = new FlowNetwork();
        flow.setup(n * 100 + 2);
        for (int i = 0; i < n; i++) {
            flow.addEdge(n * 100, i, cnt[i], 0);
        }
        for (int i = 0; i < 100; i++) {
            flow.addEdge(i * n, n * 100 + 1, k, c * i);
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 99; j++) {
                flow.addEdge(j * n + i, (j + 1) * n + i, k, 0);
            }
            for (int to : e[i]) {
                for (int j = 0; j < 99; j++) {
                    for (int u = 0; u < k; u++) {
                        int cost = (u + 1) * (u + 1) * d - u * u * d;
                        flow.addEdge(j * n + i, (j + 1) * n + to, 1, cost);
                    }
                }
            }
        }
        System.out.println(flow.minCostFlow(n * 100, n * 100 + 1, k));
    }
}
